(function(g){'use strict';var KEY='hooklab_audit_admission_queue_v0_1';function load(){try{return JSON.parse(localStorage.getItem(KEY))||{schema:'HOOKLAB_AUDIT_QUEUE_v0.1',items:[]}}catch(e){return{schema:'HOOKLAB_AUDIT_QUEUE_v0.1',items:[]}}}function save(x){localStorage.setItem(KEY,JSON.stringify(x));return x}function enqueue(pkg,flags){var s=load(),id=pkg.case_id||('CASE_'+Date.now()),item={case_id:id,feature_package:pkg,flags:flags||[],audit_state:'PENDING',scientific_state:'NOT_YET_ADMITTED',created_at:new Date().toISOString(),decision:null};var i=s.items.findIndex(x=>x.case_id===id);if(i>=0)s.items[i]=item;else s.items.push(item);return save(s)}function decide(id,decision,actor,note){var s=load(),x=s.items.find(z=>z.case_id===id);if(!x)throw Error('CASE_NOT_FOUND');if(!['ADMIT','REJECT','REVIEW'].includes(decision))throw Error('INVALID_DECISION');x.decision={decision:decision,actor:actor||'HUMAN_AUDITOR',note:note||'',at:new Date().toISOString()};x.audit_state=decision==='REVIEW'?'REVIEW_REQUIRED':'AUDITED';x.scientific_state=decision==='ADMIT'?'ADMITTED':decision==='REJECT'?'REJECTED':'NOT_YET_ADMITTED';return save(s)}function admitted(){return load().items.filter(x=>x.scientific_state==='ADMITTED')}g.HookLabAuditQueue={version:'0.1',load:load,enqueue:enqueue,decide:decide,admitted:admitted}})(window);